INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('9c5fd05cfc4997b6ee3b','Pediatric amedex 2025.pdf','28','Paediatrics','An eight-month-old male infant is brought to your office with a history of vomiting and diarrhea. Urine dipstick
examination suggests urinary tract infection. The child is not dehydrated but seems slightly ill. Which one of the following
is the next best step in management?','{"A":"A. Give antibiotics.","B":"OB. Give antibiotics and refer for ultrasound.","C":"C. Investigate for a sexually transmitted infection.","D":"D. Notify child protection services.","E":"E. Oral rehydration and discharging home."}','B','Urinary tract infection (UTI) in children may arise from urogenital abnormalities such as vesicoureteric reflux. For this
reason, in addition to treatment with antibiotics, an ultrasound scan of the kidney, ureter and bladder should be
considered in all children younger than 3 years of age (2-36 months in most guidelines) with the first episode of UTI.

Also, ultrasound is also indicated for children with UT1 if:

¢ Concurrent bacteremia

¢ Atypical UTI organisms: i.e., Staphylococcus aureus, Pseudomonas
¢ Non/inadequate response to 48hrs of IV antibiotics

¢ Abdominal mass

e¢ Abnormal voiding

¢ Recurrent UTI

e First febrile UTI and no prompt follow-up assured

¢ Renal impairment

¢ Significant electrolyte abnormalities

¢ No antenatal renal tract imaging in the second to third trimester

In children less than one-year-old, an ultrasound should be performed first. If the ultrasound is normal, voiding
cystoureterogram (VCU) would be the next step. This approach is adopted for early detection of urologic structural
abnormalities as well as possible vesicoureteric reflux.

In children older than one year of age, ultrasound alone is the investigation of choice for excluding vesicoureteric reflux.
Approximately 40% of the children with UTI have vesicoureteric reflux.

Vesicoureteric reflux can result in scarring of the kidneys, hypertension and chronic renal failure. Early detection of
vesicoureteric reflux helps prevent such complications.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[28],"source_qid":null,"duplicate_group_id":"exact-1b9843d7e3d1","duplicate_sources":[{"record_id":"9c5fd05cfc4997b6ee3b","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":28,"source_qid":null},{"record_id":"b5d24524f14f10658fd4","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":31,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"9c5fd05cfc4997b6ee3b","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":28,"supporting_pages":[28],"source_qid":null,"domain_hint":"Paediatrics","stem":"An eight-month-old male infant is brought to your office with a history of vomiting and diarrhea. Urine dipstick\nexamination suggests urinary tract infection. The child is not dehydrated but seems slightly ill. Which one of the following\nis the next best step in management?","options":{"A":"A. Give antibiotics.","B":"OB. Give antibiotics and refer for ultrasound.","C":"C. Investigate for a sexually transmitted infection.","D":"D. Notify child protection services.","E":"E. Oral rehydration and discharging home."},"source_answer":"B","source_explanation":"Urinary tract infection (UTI) in children may arise from urogenital abnormalities such as vesicoureteric reflux. For this\nreason, in addition to treatment with antibiotics, an ultrasound scan of the kidney, ureter and bladder should be\nconsidered in all children younger than 3 years of age (2-36 months in most guidelines) with the first episode of UTI.\n\nAlso, ultrasound is also indicated for children with UT1 if:\n\n¢ Concurrent bacteremia\n\n¢ Atypical UTI organisms: i.e., Staphylococcus aureus, Pseudomonas\n¢ Non/inadequate response to 48hrs of IV antibiotics\n\n¢ Abdominal mass\n\ne¢ Abnormal voiding\n\n¢ Recurrent UTI\n\ne First febrile UTI and no prompt follow-up assured\n\n¢ Renal impairment\n\n¢ Significant electrolyte abnormalities\n\n¢ No antenatal renal tract imaging in the second to third trimester\n\nIn children less than one-year-old, an ultrasound should be performed first. If the ultrasound is normal, voiding\ncystoureterogram (VCU) would be the next step. This approach is adopted for early detection of urologic structural\nabnormalities as well as possible vesicoureteric reflux.\n\nIn children older than one year of age, ultrasound alone is the investigation of choice for excluding vesicoureteric reflux.\nApproximately 40% of the children with UTI have vesicoureteric reflux.\n\nVesicoureteric reflux can result in scarring of the kidneys, hypertension and chronic renal failure. Early detection of\nvesicoureteric reflux helps prevent such complications.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","antibiotic","guideline","hypertension","management","treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"1b9843d7e3d172d57e7ab9b22c872df5c4bdc92d","duplicate_group_id":"exact-1b9843d7e3d1","duplicate_sources":[{"record_id":"9c5fd05cfc4997b6ee3b","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":28,"source_qid":null},{"record_id":"b5d24524f14f10658fd4","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":31,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
