INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('77a094cdba8a92d9b50b','Pediatric amedex 2025.pdf','31','Paediatrics','A 3-year-old girl is brought to your practice by her mother with complaint of multiple painful small oral
ulcers. The child refuses to eat because of the pain. On examination, the child is found to have a
temperature of 38°C. Similar ulcers are noted on his hand and feet. Which one of the following is the
causative organism?','{"A":"A. Herpes simplex virus (HSV).","B":"B. Group B streptococcus (GBS).","C":"OC. Coxsackie A virus.","D":"D. Adenovirus.","E":"E. Coronavirus."}','C','The clinical picture of ulcers in mouth and on hands and feet is highly suggestive of ‘hand, foot and
mouth (HFM) disease’. This often self-limiting mild viral infection is causes by Coxsackie A virus. The
disease has an incubation period of 3 to 5 days. The illness begins with a prodromal syndrome

of mild fever, headache and malaise, followed by appearance of the rash after 1 to 2 days. The rash
starts as an erythematous macular rash, progressing to gray vesicles with surrounding erythema.
These vesicles form shallow ulcers on buccal mucosa, gums and tongue. Hands and feet, especially
the lateral borders, are affected as well. It is not uncommon to see the rash on buttocks and

genitalia as well.

The rash resolves in 3 to 5 days with no scarring. The child is infectious until blisters disappear, but
the virus can be secreted into saliva and feces.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[31],"source_qid":null,"duplicate_group_id":"exact-9e6704051358","duplicate_sources":[{"record_id":"77a094cdba8a92d9b50b","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":31,"source_qid":null},{"record_id":"3a4d043e22dae4450c5c","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":73,"source_qid":null},{"record_id":"6fbcd6b1ce46e70a3bcf","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1344,"source_qid":"1145"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"77a094cdba8a92d9b50b","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":31,"supporting_pages":[31],"source_qid":null,"domain_hint":"Paediatrics","stem":"A 3-year-old girl is brought to your practice by her mother with complaint of multiple painful small oral\nulcers. The child refuses to eat because of the pain. On examination, the child is found to have a\ntemperature of 38°C. Similar ulcers are noted on his hand and feet. Which one of the following is the\ncausative organism?","options":{"A":"A. Herpes simplex virus (HSV).","B":"B. Group B streptococcus (GBS).","C":"OC. Coxsackie A virus.","D":"D. Adenovirus.","E":"E. Coronavirus."},"source_answer":"C","source_explanation":"The clinical picture of ulcers in mouth and on hands and feet is highly suggestive of ‘hand, foot and\nmouth (HFM) disease’. This often self-limiting mild viral infection is causes by Coxsackie A virus. The\ndisease has an incubation period of 3 to 5 days. The illness begins with a prodromal syndrome\n\nof mild fever, headache and malaise, followed by appearance of the rash after 1 to 2 days. The rash\nstarts as an erythematous macular rash, progressing to gray vesicles with surrounding erythema.\nThese vesicles form shallow ulcers on buccal mucosa, gums and tongue. Hands and feet, especially\nthe lateral borders, are affected as well. It is not uncommon to see the rash on buttocks and\n\ngenitalia as well.\n\nThe rash resolves in 3 to 5 days with no scarring. The child is infectious until blisters disappear, but\nthe virus can be secreted into saliva and feces.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"9e670405135839f2e753b5ce269c0011faf42ec4","duplicate_group_id":"exact-9e6704051358","duplicate_sources":[{"record_id":"77a094cdba8a92d9b50b","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":31,"source_qid":null},{"record_id":"3a4d043e22dae4450c5c","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":73,"source_qid":null},{"record_id":"6fbcd6b1ce46e70a3bcf","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1344,"source_qid":"1145"}]}',1,'v2.9.4','2026-0