INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a3085612c63214492cde','Pediatric amedex 2025.pdf','38','Paediatrics','A mother has brought her 9-month old boy to the Emergency Department with dyspnea and poor
feeding. On examination, his chest is hyperinflated, and subcostal recession is noted. On
auscultation, there are widespread fine inspiratory crackles and expiratory wheezes. Which one of
the following is the next best step in management?','{"A":"A. Nebulized adrenaline.","B":"OB. 100% oxygen via nasal prongs.","C":"C. Intravenous corticosteroids.","D":"D. Intravenous ceftriaxone.","E":"E. 100% oxygen via facemask."}','B','This clinical presentation in this 9-month old infant is classic for acute bronchiolitis, a viral illness
most commonly caused by respiratory syncytial virus (RSV). The usual age for the disease is
between 2 weeks to 9 months of age.

The classic clinical presentation is prodromal symptoms (cough, coryza) followed by wheezy
breathing, tachypnea and hyperinflated chest with subcostal recessions. In children with
bronchiolitis, oxygen therapy should be used when oxygen saturations are persistently less than
90%. Infants with bronchiolitis will have brief episodes of mild/moderate desaturations to levels less
than 90% but these brief desaturations are not a reason to start oxygen therapy.

If required, oxygen 100% should be given via nasal cannula and discontinued when oxygen
saturations are persistently greater than or equal to 90%.

Dehydration is also a serious problem in children with severe bronchiolitis and requires rehydration
using intravenous fluids or nasogastric tube.

Antibiotics are not indicated, unless a bacterial infection is suspected. There is no evidence to
support the use of nebulized adrenaline, bronchodilators or corticosteroids in children with
bronchiolitis.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[38],"source_qid":null,"duplicate_group_id":"exact-021bf3c47c6d","duplicate_sources":[{"record_id":"a3085612c63214492cde","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":38,"source_qid":null},{"record_id":"baa0e56fc6bfa6febbd2","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":197,"source_qid":null},{"record_id":"359c47504365f2b1148d","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1249,"source_qid":"333"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"a3085612c63214492cde","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":38,"supporting_pages":[38],"source_qid":null,"domain_hint":"Paediatrics","stem":"A mother has brought her 9-month old boy to the Emergency Department with dyspnea and poor\nfeeding. On examination, his chest is hyperinflated, and subcostal recession is noted. On\nauscultation, there are widespread fine inspiratory crackles and expiratory wheezes. Which one of\nthe following is the next best step in management?","options":{"A":"A. Nebulized adrenaline.","B":"OB. 100% oxygen via nasal prongs.","C":"C. Intravenous corticosteroids.","D":"D. Intravenous ceftriaxone.","E":"E. 100% oxygen via facemask."},"source_answer":"B","source_explanation":"This clinical presentation in this 9-month old infant is classic for acute bronchiolitis, a viral illness\nmost commonly caused by respiratory syncytial virus (RSV). The usual age for the disease is\nbetween 2 weeks to 9 months of age.\n\nThe classic clinical presentation is prodromal symptoms (cough, coryza) followed by wheezy\nbreathing, tachypnea and hyperinflated chest with subcostal recessions. In children with\nbronchiolitis, oxygen therapy should be used when oxygen saturations are persistently less than\n90%. Infants with bronchiolitis will have brief episodes of mild/moderate desaturations to levels less\nthan 90% but these brief desaturations are not a reason to start oxygen therapy.\n\nIf required, oxygen 100% should be given via nasal cannula and discontinued when oxygen\nsaturations are persistently greater than or equal to 90%.\n\nDehydration is also a serious problem in children with severe bronchiolitis and requires rehydration\nusing intravenous fluids or nasogastric tube.\n\nAntibiotics are not indicated, unless a bacterial infection is suspected. There is no evidence to\nsupport the use of nebulized adrenaline, bronchodilators or corticosteroids in children with\nbronchiolitis.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","antibiotic","management","therapy"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"021bf3c47c6dfe4945b771ae37237a6014b8cbc5","duplicate_group_id":"exact-021bf3c47c6d","duplicate_sources":[{"record_id":"a3085612c63214492cde","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":38,"source_qid":null},{"record_id":"baa0e56fc6bfa6febbd2","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":197,"source_qid":null},{"record_id":"359c47504365f2b1148d","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1249,"source_qid":"333"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
