INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('e1dff08cf3658eb067e4','Pediatric amedex 2025.pdf','42','Paediatrics','A mother brings her 3-week-old male baby to the Emergency Department because of his loose
bloody bowel motions. The mother says the diarrhea has started 2 days ago after she started her
son on formula milk. The mother is lactose-intolerant and does not use dairy products. On
examination, the child is mildly dehydrated and has an eczematous rash on his right cheek. He is
not febrile. The rest of the exam is inconclusive. Family history is remarkable for atopy including
asthma and eczema in his father and older sister. Mother is concerned that his son may have the
same allergy to milk and dairy product she has. Which one of the following is the most likely
diagnosis?','{"A":"A. Lactose intolerance.","B":"B. Gastroenteritis.","C":"C. Galactosemia.","D":"D. Fructose intolerance.","E":"OE. Cow''s milk protein intolerance."}','E','The onset of bloody diarrhea shortly after introduction of formula, the presence of eczema, and
family history of atopy makes cow’s milk protein allergy (intolerance) (CMPA) the most likely
diagnosis with high certainty.

CMPA results from an immunological reaction to one or more milk proteins. This immunological
basis distinguishes CMPA from other adverse reactions to cow’s milk protein such as lactose
intolerance.

CMPA may be immunoglobulin E (IgE) or non-IgE associated. In IgE-associated cases, CMPA may
be a manifestation of the atopic diathesis. These reactions may occur as short as minutes after
ingestion of cow’s milk or cow’s milk-based formula. These early reactions usually manifest as
urticaria, angioedema, vomiting or an acute flare of atopic dermatitis. The remaining 42% show a
later reaction, typically atopic dermatitis or gastrointestinal disturbances.

Even small amounts of cow’s milk in breast milk of mother’s who take dairy products may trigger the
condition.

Other options do not justify the clinical presentation.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[42],"source_qid":null,"duplicate_group_id":"exact-a1894c1ba896","duplicate_sources":[{"record_id":"e1dff08cf3658eb067e4","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":42,"source_qid":null},{"record_id":"17fec2b6f89c32373650","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (2).pdf","source_page":179,"source_qid":null},{"record_id":"7c381970dd00abc41b02","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1311,"source_qid":"815"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"e1dff08cf3658eb067e4","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":42,"supporting_pages":[42],"source_qid":null,"domain_hint":"Paediatrics","stem":"A mother brings her 3-week-old male baby to the Emergency Department because of his loose\nbloody bowel motions. The mother says the diarrhea has started 2 days ago after she started her\nson on formula milk. The mother is lactose-intolerant and does not use dairy products. On\nexamination, the child is mildly dehydrated and has an eczematous rash on his right cheek. He is\nnot febrile. The rest of the exam is inconclusive. Family history is remarkable for atopy including\nasthma and eczema in his father and older sister. Mother is concerned that his son may have the\nsame allergy to milk and dairy product she has. Which one of the following is the most likely\ndiagnosis?","options":{"A":"A. Lactose intolerance.","B":"B. Gastroenteritis.","C":"C. Galactosemia.","D":"D. Fructose intolerance.","E":"OE. Cow''s milk protein intolerance."},"source_answer":"E","source_explanation":"The onset of bloody diarrhea shortly after introduction of formula, the presence of eczema, and\nfamily history of atopy makes cow’s milk protein allergy (intolerance) (CMPA) the most likely\ndiagnosis with high certainty.\n\nCMPA results from an immunological reaction to one or more milk proteins. This immunological\nbasis distinguishes CMPA from other adverse reactions to cow’s milk protein such as lactose\nintolerance.\n\nCMPA may be immunoglobulin E (IgE) or non-IgE associated. In IgE-associated cases, CMPA may\nbe a manifestation of the atopic diathesis. These reactions may occur as short as minutes after\ningestion of cow’s milk or cow’s milk-based formula. These early reactions usually manifest as\nurticaria, angioedema, vomiting or an acute flare of atopic dermatitis. The remaining 42% show a\nlater reaction, typically atopic dermatitis or gastrointestinal disturbances.\n\nEven small amounts of cow’s milk in breast milk of mother’s who take dairy products may trigger the\ncondition.\n\nOther options do not justify the clinical presentation.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["asthma"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"a1894c1ba8964b967b25cf94a614e4dfd43a7e41","duplicate_group_id":"exact-a1894c1ba896","duplicate_sources":[{"record_id":"e1dff08cf3658eb067e4","record_type":"text_mcq","source_file":"Pediatric amedex 2025