INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('78db1cd09d61632d6a37','Pediatric amedex 2025.pdf','51','Paediatrics','Which one of the following can be an alarming sign in a 2-month old infant?','{"A":"OA. Inability to smile at people.","B":"B. Inability to hold neck.","C":"C. Inability to explore things by holding and looking at them and putting them in mouth.","D":"D. Does not seem to recognize mother.","E":"E. Does not seem interested in activities around them."}','A','Normally, social smile develops at 6 weeks of age; therefore its absence in a 2-month-old baby
could be concerning.

(Option A) The ability to hold the neck is obtained at around 3 months.

(Option B) Ability to explore things by holding, looking at them and putting them in mouth is
achieved by 6 months of age.

(Option D) A skill to recognize mother’s face is achieved at the age of 3 months.

(Option E) The child starts to show interest in the activities around them at about 9 months of age.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[51],"source_qid":null,"duplicate_group_id":"exact-0dc62a8d59ce","duplicate_sources":[{"record_id":"78db1cd09d61632d6a37","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":51,"source_qid":null},{"record_id":"d3c8fb4c6fc5219a12d1","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":77,"source_qid":null},{"record_id":"5a2472ead6c10a54ce74","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1260,"source_qid":"342"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"78db1cd09d61632d6a37","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":51,"supporting_pages":[51],"source_qid":null,"domain_hint":"Paediatrics","stem":"Which one of the following can be an alarming sign in a 2-month old infant?","options":{"A":"OA. Inability to smile at people.","B":"B. Inability to hold neck.","C":"C. Inability to explore things by holding and looking at them and putting them in mouth.","D":"D. Does not seem to recognize mother.","E":"E. Does not seem interested in activities around them."},"source_answer":"A","source_explanation":"Normally, social smile develops at 6 weeks of age; therefore its absence in a 2-month-old baby\ncould be concerning.\n\n(Option A) The ability to hold the neck is obtained at around 3 months.\n\n(Option B) Ability to explore things by holding, looking at them and putting them in mouth is\nachieved by 6 months of age.\n\n(Option D) A skill to recognize mother’s face is achieved at the age of 3 months.\n\n(Option E) The child starts to show interest in the activities around them at about 9 months of age.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"0dc62a8d59ce24afb7074e23cd01d01e475b7def","duplicate_group_id":"exact-0dc62a8d59ce","duplicate_sources":[{"record_id":"78db1cd09d61632d6a37","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":51,"source_qid":null},{"record_id":"d3c8fb4c6fc5219a12d1","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":77,"source_qid":null},{"record_id":"5a2472ead6c10a54ce74","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1260,"source_qid":"342"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current