INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('3722e2ef1091827b5680','Pediatric amedex 2025.pdf','55','Paediatrics','A 6-year-old girl is brought to your practice by her parents with a 4-day history of bilateral knee
and ankle pain. On examination, she has a temperature of 37.6 C. Her joints are tender but there
is no swelling, inflammation, or synovial thickening. The full range of motion of the joints is
preserved. Palpable purpuric rashes are noted on her legs and buttocks with some ecchymoses
around her ankles. Full blood count, blood urea, electrolytes and liver function tests are normal.
ESR is 10mm/hr. which one of the following is a known complication of this girl’s condition?','{"A":"A. Pleurisy.","B":"B. Fasciitis.","C":"OC. Nepnhritis.","D":"D. Thrombocytopenia.","E":"E. Diabetes mellitus."}','C','The clinical picture is highly suggestive of Hendch-Schonlein purpura (HSP).

HSP, also known as anaphylactoid purpura, is an acute immune-mediated vasculitis of unknown
cause. It is characterized by arthralgia (not arthritis), and non-thrombocytopenic purpura (the
purpura is vascular due to leukoclastic activity) with typical distribution over legs and buttock.

Other clinical manifestations HSP include colicky abdominal pain, melena, swelling of the joints
especially the ankles, and nephritis. The arthralgia and abdominal pain may persist for 2 to 4
weeks.

Nephritis of HSP, which is histologically the same as the IgA nephropathy, may occur in a small
percentage of patients. For this reason, all patients with HSP should have a urinalysis. If the
patient is found to have hematuria, long-term follow-up is required.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[55],"source_qid":null,"duplicate_group_id":"exact-0479d2300931","duplicate_sources":[{"record_id":"3722e2ef1091827b5680","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":55,"source_qid":null},{"record_id":"a29ad8b8f4a069f16978","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1325,"source_qid":"112"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"3722e2ef1091827b5680","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":55,"supporting_pages":[55],"source_qid":null,"domain_hint":"Paediatrics","stem":"A 6-year-old girl is brought to your practice by her parents with a 4-day history of bilateral knee\nand ankle pain. On examination, she has a temperature of 37.6 C. Her joints are tender but there\nis no swelling, inflammation, or synovial thickening. The full range of motion of the joints is\npreserved. Palpable purpuric rashes are noted on her legs and buttocks with some ecchymoses\naround her ankles. Full blood count, blood urea, electrolytes and liver function tests are normal.\nESR is 10mm/hr. which one of the following is a known complication of this girl’s condition?","options":{"A":"A. Pleurisy.","B":"B. Fasciitis.","C":"OC. Nepnhritis.","D":"D. Thrombocytopenia.","E":"E. Diabetes mellitus."},"source_answer":"C","source_explanation":"The clinical picture is highly suggestive of Hendch-Schonlein purpura (HSP).\n\nHSP, also known as anaphylactoid purpura, is an acute immune-mediated vasculitis of unknown\ncause. It is characterized by arthralgia (not arthritis), and non-thrombocytopenic purpura (the\npurpura is vascular due to leukoclastic activity) with typical distribution over legs and buttock.\n\nOther clinical manifestations HSP include colicky abdominal pain, melena, swelling of the joints\nespecially the ankles, and nephritis. The arthralgia and abdominal pain may persist for 2 to 4\nweeks.\n\nNephritis of HSP, which is histologically the same as the IgA nephropathy, may occur in a small\npercentage of patients. For this reason, all patients with HSP should have a urinalysis. If the\npatient is found to have hematuria, long-term follow-up is required.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"0479d2300931103e5a0b49fa2b8ce98d703d32bf","duplicate_group_id":"exact-0479d2300931","duplicate_sources":[{"record_id":"3722e2ef1091827b5680","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":55,"source_qid":null},{"record_id":"a29ad8b8f4a069f16978","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1325,"source_qid":"112"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=exclude