INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('b62c03998c5c39b0fc9d','Pediatric amedex 2025.pdf','71','Paediatrics','Does the child or adolescent have all of the following:
Fever for 2 3 days
Epidemiological link to SARS-CoV-2 infection
At least 2 of the following suggestive clinical features:
Rash, non-purulent conjunctivitis +/- mucocutaneous inflammation
Hypotension
Myocardial dysfunction, pericarditis, valvulitis or coronary
abnormalities
Coagulopathy
Gastrointestinal symptoms
There is considerable overlap in
the clinical presentation of PIMS-
TS with that of other fever and
rash syndromes. A comprehensive
assessment of other, non PIMS-TS
aetiologies is imperative.
Have other causes of
systemic inflammation
been considered in the
evaluation?
Continue diagnostic evaluation
as per standard of care and
monitor for PIMS-TS features,
particularly if there is an
epidemiological link to SARS-
CoV-2 infection.
Commence
investigations for child
with possible PIMS-TS
CRP and ESR +/-
procalcitonin
FBC
UEC and LFTs
Coagulation profile
D-Dimer
Troponin
LDH
SARS-CoV-2 serology
Biofire respiratory PCR panel
Are inflammatory markers
(CRP, ESR &/or procalcitonin)
elevated?',NULL,NULL,NULL,'{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[71],"source_qid":null,"duplicate_group_id":"exact-c8c50aa406c2","duplicate_sources":[{"record_id":"b62c03998c5c39b0fc9d","record_type":"visual_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":71,"source_qid":null}],"parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","parser_mode":"v282_visual_page_asset","text_method":"source_page_image+best_available_text","visual_asset":"visual_assets/Pediatric_amedex_2025__fe3883efd6a6/page_00071.jpg","asset_preview_url":"https://drive.google.com/file/d/1GXQ4jhcXsvBz9KZhRFKpcnugKZod-vts/preview"}','visual_assets/Pediatric_amedex_2025__fe3883efd6a6/page_00071.jpg','https://drive.google.com/thumbnail?id=1GXQ4jhcXsvBz9KZhRFKpcnugKZod-vts&sz=w1600','source_page_image',NULL,'needs_verification','[]','low','{"record_id":"b62c03998c5c39b0fc9d","record_type":"visual_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":71,"supporting_pages":[71],"source_qid":null,"domain_hint":"Paediatrics","stem":"Does the child or adolescent have all of the following:\nFever for 2 3 days\nEpidemiological link to SARS-CoV-2 infection\nAt least 2 of the following suggestive clinical features:\nRash, non-purulent conjunctivitis +/- mucocutaneous inflammation\nHypotension\nMyocardial dysfunction, pericarditis, valvulitis or coronary\nabnormalities\nCoagulopathy\nGastrointestinal symptoms\nThere is considerable overlap in\nthe clinical presentation of PIMS-\nTS with that of other fever and\nrash syndromes. A comprehensive\nassessment of other, non PIMS-TS\naetiologies is imperative.\nHave other causes of\nsystemic inflammation\nbeen considered in the\nevaluation?\nContinue diagnostic evaluation\nas per standard of care and\nmonitor for PIMS-TS features,\nparticularly if there is an\nepidemiological link to SARS-\nCoV-2 infection.\nCommence\ninvestigations for child\nwith possible PIMS-TS\nCRP and ESR +/-\nprocalcitonin\nFBC\nUEC and LFTs\nCoagulation profile\nD-Dimer\nTroponin\nLDH\nSARS-CoV-2 serology\nBiofire respiratory PCR panel\nAre inflammatory markers\n(CRP, ESR &/or procalcitonin)\nelevated?","options":null,"options_mode":"source_page_image","visual_asset":"visual_assets/Pediatric_amedex_2025__fe3883efd6a6/page_00071.jpg","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v282_visual_page_asset","text_method":"source_page_image+best_available_text","parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","stem_hash":"c8c50aa406c2591244004295a9255cde276e93aa","duplicate_group_id":"exact-c8c50aa406c2","duplicate_sources":[{"record_id":"b62c03998c5c39b0fc9d","record_type":"visual_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":71,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.