INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('5e9fb03224d1dc87d693','Pediatric amedex 2025.pdf','76','Paediatrics','A 10-year-old girl is being assessed in your clinic with complaints of labial fusion. She has the
past history of vulvovaginitis which has been successfully treated. The child reports no voiding
difficulties. Which one of the following is the most appropriate next step in management?','{"A":"OA. Reassurance.","B":"B. Surgical separation of adhesions.","C":"C. Encourage good hygiene.","D":"D. Antibiotics.","E":"E. Manual separation of adhesions."}','A','Labial adhesion (labial agglutination) occurs when the medial edges of the labia minora becomes
adherent, often in the background history of vulvovaginitis. This is probably due to combination of
thin vaginal mucosa (the normal prepubescent state) and minor irritation (Such as in
vulvovaginitis).

This is a normal variant and will resolve spontaneously in late childhood. Provided that the child
is able to void easily, no treatment other than reassurance is required.

(Option B) Surgical separation of the adhesions, followed by application of Vaseline and/or
estrogen cream can be considered for children with urinary symptoms. This method, however, is
not generally recommended because of the high recurrence rates.

(Option C) Encouraging good hygiene, althoug a good advice, is not effective in treatment of the
condition.

(Option D) Antibitoics have no role in management of labial adhesions.

(Option E) Manual separation of adhesions can be distressing for the child and is associated
with a high risk of recurrence and not recommended.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[76],"source_qid":null,"duplicate_group_id":"exact-cb5d4ffe992f","duplicate_sources":[{"record_id":"5e9fb03224d1dc87d693","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":76,"source_qid":null},{"record_id":"02d69886c51a69cdaaa4","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":26,"source_qid":null},{"record_id":"32b0cd7e4c7ea58fe0c3","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1333,"source_qid":"1008"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"5e9fb03224d1dc87d693","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":76,"supporting_pages":[76],"source_qid":null,"domain_hint":"Paediatrics","stem":"A 10-year-old girl is being assessed in your clinic with complaints of labial fusion. She has the\npast history of vulvovaginitis which has been successfully treated. The child reports no voiding\ndifficulties. Which one of the following is the most appropriate next step in management?","options":{"A":"OA. Reassurance.","B":"B. Surgical separation of adhesions.","C":"C. Encourage good hygiene.","D":"D. Antibiotics.","E":"E. Manual separation of adhesions."},"source_answer":"A","source_explanation":"Labial adhesion (labial agglutination) occurs when the medial edges of the labia minora becomes\nadherent, often in the background history of vulvovaginitis. This is probably due to combination of\nthin vaginal mucosa (the normal prepubescent state) and minor irritation (Such as in\nvulvovaginitis).\n\nThis is a normal variant and will resolve spontaneously in late childhood. Provided that the child\nis able to void easily, no treatment other than reassurance is required.\n\n(Option B) Surgical separation of the adhesions, followed by application of Vaseline and/or\nestrogen cream can be considered for children with urinary symptoms. This method, however, is\nnot generally recommended because of the high recurrence rates.\n\n(Option C) Encouraging good hygiene, althoug a good advice, is not effective in treatment of the\ncondition.\n\n(Option D) Antibitoics have no role in management of labial adhesions.\n\n(Option E) Manual separation of adhesions can be distressing for the child and is associated\nwith a high risk of recurrence and not recommended.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"cb5d4ffe992f227655df0216caebbd49f4404f91","duplicate_group_id":"exact-cb5d4ffe992f","duplicate_sources":[{"record_id":"5e9fb03224d1dc87d693","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":76,"source_qid":null},{"record_id":"02d69886c51a69cdaaa4","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":26,"source_qid":null},{"record_id":"32b0cd7e4c7ea