INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('9e96f4d3174cff23a4cb','Pediatric amedex 2025.pdf','80','Paediatrics','The parents of John, six years old, have brought him to your GP practice because he was bullied in
school. When you start talking to him by asking how he is feeling today, he says anxiously, “I | |...wan ‘n
‘n ttt to ttoo go o home.” He is otherwise normal with no remarkable physical findings. According to the
parents, he has met developmental milestones otherwise. Which one of the following is the most
important initial step in management?','{"A":"OA. Referring the child to a speech therapist.","B":"B. Referring the patient to a pediatric psychiatrist.","C":"C. Telling the child to speak slowly.","D":"D. Enforcing reward and punishment strategy.","E":"E. Arranging for school observation."}','A','Stuttering or stammering is a speech disorder characterized by interruptions to speech such as
hesitating, repeating sounds and words, or prolonging sounds. The cause is unknown, but genetics may
be a factor. Anxiety and stress do not cause stuttering but can make it worse.

About 1 in 100 Australians stutter. The condition can affect children, adolescents, and adults. It usually
starts in childhood, between the ages of around 2 and 4, although it can also start later. Stuttering can
start overnight or build up over time.

Up to 1 in 12 three-year-old children stutter, but approximately three-quarters of them will recover without
any treatment — although it might take a few years. Persisting stutter beyond adolescence is unlikely to
spontaneously recover.

It is important that any child who stutters is promptly referred to a speech therapist/pathologist for
appropriate assessment. The earlier a child starts treatment, the better the prognosis. The best evidence
from clinical trials for treating children who stutter is the Lidcombe Program of Early Stuttering
Intervention. This is a behavior modification treatment. The main principles involve praising a child when
words are spoken clearly and occasionally noting when stuttering has occurred.

A psychiatrist referral (option B) is not the appropriate initial step if the child appears to have no
developmental delays otherwise.

Asking the child to speak slowly (option C) is not the appropriate response or treatment.

A reward-and-punishment strategy (option D) is also inappropriate because punishing the child may
induce further stress and cause even more stuttering.

School observation (option E) is not indicated at this stage since the child has already presented to your
clinic with the condition.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[80],"source_qid":null,"duplicate_group_id":"exact-fd5f22abbd4a","duplicate_sources":[{"record_id":"9e96f4d3174cff23a4cb","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":80,"source_qid":null},{"record_id":"43a8ba8ee863425bc428","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":207,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"9e96f4d3174cff23a4cb","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":80,"supporting_pages":[80],"source_qid":null,"domain_hint":"Paediatrics","stem":"The parents of John, six years old, have brought him to your GP practice because he was bullied in\nschool. When you start talking to him by asking how he is feeling today, he says anxiously, “I | |...wan ‘n\n‘n ttt to ttoo go o home.” He is otherwise normal with no remarkable physical findings. According to the\nparents, he has met developmental milestones otherwise. Which one of the following is the most\nimportant initial step in management?","options":{"A":"OA. Referring the child to a speech therapist.","B":"B. Referring the patient to a pediatric psychiatrist.","C":"C. Telling the child to speak slowly.","D":"D. Enforcing reward and punishment strategy.","E":"E. Arranging for school observation."},"source_answer":"A","source_explanation":"Stuttering or stammering is a speech disorder characterized by interruptions to speech such as\nhesitating, repeating sounds and words, or prolonging sounds. The cause is unknown, but genetics may\nbe a factor. Anxiety and stress do not cause stuttering but can make it worse.\n\nAbout 1 in 100 Australians stutter. The condition can affect children, adolescents, and adults. It usually\nstarts in childhood, between the ages of around 2 and 4, although it can also start later. Stuttering can\nstart overnight or build up over time.\n\nUp to 1 in 12 three-year-old children stutter, but approximately three-quarters of them will recover without\nany treatment — although it might take a few years. Persisting stutter beyond adolescence is unlikely to\nspontaneously recover.\n\nIt is important that any child who stutters is promptly referred to a speech therapist/pathologist for\nappropriate assessment. The earlier a child starts treatment, the better the prognosis. The best evidence\nfrom clinical trials for treating children who stutter is the Lidcombe Program of Early Stuttering\nIntervention. This is a behavior modification treatment. The main principles involve praising a child when\nwords are spoken clearly and occasionally noting when stuttering has occurred.\n\nA psychiatrist referral (option B) is not the appropriate initial step if the child appears to have no\ndevelopmental delays otherwise.\n\nAsking the child to speak slowly (option C) is not the appropriate response or treatment.\n\nA reward-and-punishment strategy (option D) is also inappropriate because punishing the child may\ninduce further stress and cause even more stuttering.\n\nSchool observation (option E) is not indicated at this stage since the child has already presented to your\nclinic with the condition.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"fd5f22abbd4a622f46df22f203fdc54fd9c3a572","duplicate_group_id":"exact-fd5f22abbd4a","duplicate_sources":[{"record_id":"9e96f4d3174cff23a4cb","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":80,"source_qid":null},{"record_id":"43a8ba8ee863425bc428","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":207,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
