INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('00b1591e025eebec1c3d','Pediatric amedex 2025.pdf','82','Paediatrics','A 4-year-old child is brought to your practice with a 2-week history of harsh cough, fever, runny
nose and dyspnea. He is short of breath on examination. Which one of the following would be the
next best step in management?','{"A":"A. Nasopharyngeal aspiration for pertussis.","B":"B. Pertussis serology.","C":"OC. Chest X-ray.","D":"D. Pulmonary function tests.","E":"E. Blood culture."}','C','With dyspnea, this child is likely to have a pulmonary pathology. Considering this, obtaining a
chest X-ray is the most appropriate initial step in management, as an attempt to assess the lungs
for the cause of this presentation.

(Options A and B) Nasopharyngeal aspiration in children (nasopharyngeal swab in adults) for
culture or serology is to confirm the diagnosis of pertussis. However, the findings in this scenario
are against pertussis, because (1) patients with pertussis are not febrile and (2) lower respiratory
tract is not involved. Unless during the bouts of cough, shorteness of breath is not a common
feature in pertussis.

(Option D) Pulmonary function test are not indicated here; at least not as an initial step.

(Option E) Blood culture can be considered as part of workup later on if indicated. An example is
when chest X-ray suggests pneumonia and measures to isolate the causative organism is
required. At this stage, however, obtaining a chest X-ray would be the most appropriate initial
step.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[82],"source_qid":null,"duplicate_group_id":"exact-16fe5b4124cc","duplicate_sources":[{"record_id":"00b1591e025eebec1c3d","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":82,"source_qid":null},{"record_id":"5dc3dfbc74de0762e1e2","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":168,"source_qid":null},{"record_id":"380b1bb6e7130ce5f6b5","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1257,"source_qid":"338"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"00b1591e025eebec1c3d","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":82,"supporting_pages":[82],"source_qid":null,"domain_hint":"Paediatrics","stem":"A 4-year-old child is brought to your practice with a 2-week history of harsh cough, fever, runny\nnose and dyspnea. He is short of breath on examination. Which one of the following would be the\nnext best step in management?","options":{"A":"A. Nasopharyngeal aspiration for pertussis.","B":"B. Pertussis serology.","C":"OC. Chest X-ray.","D":"D. Pulmonary function tests.","E":"E. Blood culture."},"source_answer":"C","source_explanation":"With dyspnea, this child is likely to have a pulmonary pathology. Considering this, obtaining a\nchest X-ray is the most appropriate initial step in management, as an attempt to assess the lungs\nfor the cause of this presentation.\n\n(Options A and B) Nasopharyngeal aspiration in children (nasopharyngeal swab in adults) for\nculture or serology is to confirm the diagnosis of pertussis. However, the findings in this scenario\nare against pertussis, because (1) patients with pertussis are not febrile and (2) lower respiratory\ntract is not involved. Unless during the bouts of cough, shorteness of breath is not a common\nfeature in pertussis.\n\n(Option D) Pulmonary function test are not indicated here; at least not as an initial step.\n\n(Option E) Blood culture can be considered as part of workup later on if indicated. An example is\nwhen chest X-ray suggests pneumonia and measures to isolate the causative organism is\nrequired. At this stage, however, obtaining a chest X-ray would be the most appropriate initial\nstep.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"16fe5b4124cc8f76347071961b763d7af61e47ff","duplicate_group_id":"exact-16fe5b4124cc","duplicate_sources":[{"record_id":"00b1591e025eebec1c3d","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":82,"source_qid":null},{"record_id":"5dc3dfbc74de0762e1e2","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (1).pdf","source_page":168,"source_qid":null},{"record_id":"380b1bb6e7130ce5f6b5","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1257,"source_qid":"338"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
