INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('546286efa4539363d483','src-v294-5083b15f',NULL,'85','Paediatrics','Paediatrics','Paediatrics','AMC MCQ','A 55-year-old child is brought to your practice by his parents with complaints of fever and ear
pain. On examination, he is in mild distress and has a fever of 38.3°C. Otoscopic examination
reveals a red bulging tympanic membrane on the right side with decreased mobility. Which one
of the following is more likely to have caused this presentation?',NULL,'B','A red bulging tympanic membrane with decreased mobility is the classic finding in acute otitis
media (AOM).

In children older than 6 weeks, AOM is caused by bacteria in majority of cases. Streptococcus
pneumoniae, Hemophilus influenzae, Moraxella catarrhalis, and Streptococcus pyogenes are
responsible for the majority of episodes of AOM in persons older than 6 weeks. Other bacteria
implicated in AOM include Staphylococcus aureus, streptococcus viridans, and Pseudomonas
aeruginosa.

Of these, Streptococcus pneumoniae is the most common etiologic agent responsible for AOM
and for invasive bacterial infections in children of all age groups, followed by Hemophilus
influenzae as the second most common etiologic factor.

RSV virus is the etiologic factor, mostly in neonates. Infection with this virus is associated with
pneumonia, bronchiolitis and otitis media in this age group; however, streptococcus pneumoniae
remains the most common etiologic factor for AOM even in this age group.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2025','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[85],"source_qid":null,"duplicate_group_id":"exact-b7981c79e99b","duplicate_sources":[{"record_id":"546286efa4539363d483","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":85,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','medium') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
