INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f97a78a153ba7ae9d286','Pediatric amedex 2025.pdf','94','Paediatrics','A 9-year-old boy is brought to your attention by his parents because of poor exercise tolerance. He is a member
of the school basketball team, but recently, it has been hard for him to play because he becomes short of breath
and tired soon after he starts playing. On examination, his height is at the 97th percentile, and his weight is at
the 3rd percentile. Which one of the following is the most important step in management?','{"A":"A. Karyotyping.","B":"B. Bone scan.","C":"OC. Cardiac ultrasound.","D":"D. Growth hormone test.","E":"E. CT scan."}','C','Marfan syndrome (MFS) should always be considered a probable diagnosis in children with tall stature and low
weight,

MFS is an autosomal dominant connective tissue disorder involving the cardiovascular, skeletal and ocular
systems, the skin, lungs and dura. The prevalence is at least 1 in 5000. In 90-93% of cases, MFS is caused by
mutations in FBN1. In a minority, MFS is caused by mutations in a second gene called TGFBR2. MFS caused
by this mutation is termed MFS2. Based on current statistics, MFS2 accounts for up to 10% of cases with MFS.

Cardinal manifestations include aortic aneurysm and dissection, ocular lens dislocation and long bone
overgrowth.

Cardiac disease is the leading cause of morbidity and mortality in patients with MFS. When the syndrome is
suspected based on clinical grounds, an echocardiogram (cardiac ultrasound scan) should follow as the most
appropriate next step in management for evaluating aortic root dilation (the most important) and mitral valve
prolapse—conditions frequently seen in patients with MFS. The former is more common and significant
Clinically.

Serial echocardiographic surveillance is indicated for all affected individuals. Frequency should be tailored to
each individual by their cardiologist. Based on current evidence, the use of beta blockers remains the first-line
treatment (except where contra-indicated, e.g., in asthmatic patients) in aortic dilatation in MFS even in young
children if a diagnosis of MFS is clear, or if there is a known FBN1 mutation in a young child without clinical
features of MFS but with affected first degree relative(s) with a known mutation and aortic root dilatation. If beta
blockers are ineffective or contraindicated, verapamil or ACE inhibitors would be the appropriate second-line
treatment option.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","supporting_pages":[94],"source_qid":null,"duplicate_group_id":"exact-a007a5961622","duplicate_sources":[{"record_id":"f97a78a153ba7ae9d286","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":94,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"f97a78a153ba7ae9d286","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_year":2025,"source_page":94,"supporting_pages":[94],"source_qid":null,"domain_hint":"Paediatrics","stem":"A 9-year-old boy is brought to your attention by his parents because of poor exercise tolerance. He is a member\nof the school basketball team, but recently, it has been hard for him to play because he becomes short of breath\nand tired soon after he starts playing. On examination, his height is at the 97th percentile, and his weight is at\nthe 3rd percentile. Which one of the following is the most important step in management?","options":{"A":"A. Karyotyping.","B":"B. Bone scan.","C":"OC. Cardiac ultrasound.","D":"D. Growth hormone test.","E":"E. CT scan."},"source_answer":"C","source_explanation":"Marfan syndrome (MFS) should always be considered a probable diagnosis in children with tall stature and low\nweight,\n\nMFS is an autosomal dominant connective tissue disorder involving the cardiovascular, skeletal and ocular\nsystems, the skin, lungs and dura. The prevalence is at least 1 in 5000. In 90-93% of cases, MFS is caused by\nmutations in FBN1. In a minority, MFS is caused by mutations in a second gene called TGFBR2. MFS caused\nby this mutation is termed MFS2. Based on current statistics, MFS2 accounts for up to 10% of cases with MFS.\n\nCardinal manifestations include aortic aneurysm and dissection, ocular lens dislocation and long bone\novergrowth.\n\nCardiac disease is the leading cause of morbidity and mortality in patients with MFS. When the syndrome is\nsuspected based on clinical grounds, an echocardiogram (cardiac ultrasound scan) should follow as the most\nappropriate next step in management for evaluating aortic root dilation (the most important) and mitral valve\nprolapse—conditions frequently seen in patients with MFS. The former is more common and significant\nClinically.\n\nSerial echocardiographic surveillance is indicated for all affected individuals. Frequency should be tailored to\neach individual by their cardiologist. Based on current evidence, the use of beta blockers remains the first-line\ntreatment (except where contra-indicated, e.g., in asthmatic patients) in aortic dilatation in MFS even in young\nchildren if a diagnosis of MFS is clear, or if there is a known FBN1 mutation in a young child without clinical\nfeatures of MFS but with affected first degree relative(s) with a known mutation and aortic root dilatation. If beta\nblockers are ineffective or contraindicated, verapamil or ACE inhibitors would be the appropriate second-line\ntreatment option.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","asthma","management","treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"a007a59616221fe02a1ee35a4679985be863d621","duplicate_group_id":"exact-a007a5961622","duplicate_sources":[{"record_id":"f97a78a153ba7ae9d286","record_type":"text_mcq","source_file":"Pediatric amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Pediatric amedex 2025.pdf","source_page":94,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
